-- 88 Night Drive: the score follows the car. Four stems start together
-- (Audio.play_music_layers) and fade in one by one as it speeds up
-- (Audio.set_music_layer); the engine is a looping sound whose pitch climbs
-- through the gears (Audio.set_sound_pitch, by the id play_sound returned);
-- R crossfades to the radio - a playlist that crossfades station to station
-- (Audio.set_playlist, Audio.next_track) - and back. Generated by
-- tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/88-night-drive.scene"
local STEMS = { "sounds/nd_pad.wav", "sounds/nd_drums.wav", "sounds/nd_bass.wav", "sounds/nd_lead.wav" }
local RADIO = { "sounds/nd_radio_coast.wav", "sounds/nd_radio_glow.wav" }
local STATIONS = { ["sounds/nd_radio_coast.wav"] = "Coastline FM", ["sounds/nd_radio_glow.wav"] = "Afterglow 124" }
local TOP = 220

local captions = true
local e = {}
local speed, scroll, spin, t = 0, 0, 0, 0
local engine
local radio = false
local wanted = { 1, 0, 0, 0 }

-- How loud each stem should be at a fraction `k` of top speed.
local function stems_for(k)
    return { 1, k > 0.12 and 1 or 0, k > 0.42 and 0.9 or 0, k > 0.72 and 0.8 or 0 }
end

function init(entity)
    for _, n in ipairs({ "Mountains", "City", "Road", "Car", "WheelBack", "WheelFront", "Underglow", "Headlight",
        "Speed", "Status", "Palm0", "Palm1", "Palm2", "Stem0", "Stem1", "Stem2", "Stem3" }) do
        e[n] = Entity.find_by_name(n)
    end
    Audio.play_music_layers(STEMS, wanted, 2)
    engine = Audio.play_sound("sounds/nd_engine.wav", 0.45, 0.6, 0, true)
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    t = t + dt

    local up = Input.is_key_pressed("Up") or Input.is_key_pressed("W")
    local down = Input.is_key_pressed("Down") or Input.is_key_pressed("S")
    if up then
        speed = math.min(TOP, speed + (80 - speed * 0.2) * dt)
    elseif down then
        speed = math.max(0, speed - 150 * dt)
    else
        speed = math.max(0, speed - 12 * dt)
    end
    local k = speed / TOP

    -- The engine climbs through four gears, dropping at each shift.
    local g = math.min(k * 4, 3.999)
    local within = g - math.floor(g)
    Audio.set_sound_pitch(engine, 0.6 + 0.45 * k + 0.5 * within)

    -- The score follows the speed; the radio does not.
    if Input.is_key_just_pressed("R") then
        radio = not radio
        if radio then
            Audio.set_playlist(RADIO, { crossfade = 2.5, loop = true, volume = 0.9 })
        else
            wanted = stems_for(k)
            Audio.play_music_layers(STEMS, wanted, 2.5)
        end
    end
    if radio and Input.is_key_just_pressed("N") then Audio.next_track() end
    if not radio then
        local now = stems_for(k)
        for i = 1, 4 do
            if now[i] ~= wanted[i] then
                wanted[i] = now[i]
                Audio.set_music_layer(i, now[i], 1.5)
            end
        end
    end
    for i = 1, 4 do
        local v = radio and 0 or Audio.get_music_layer(i)
        Transform.set_scale(e["Stem" .. (i - 1)], math.max(v, 0.001), 1)
    end

    -- The world goes by: far things slowly, near things fast.
    scroll = scroll + speed * dt * 7
    Transform.set_position(e.Mountains, -(scroll * 0.04 % 1024), 0)
    Transform.set_position(e.City, -(scroll * 0.18 % 1024), 20)
    Transform.set_position(e.Road, -(scroll % 256), -250)
    for i = 0, 2 do
        local x = ((640 * i - scroll * 0.6) % 1920) - 960
        Transform.set_position(e["Palm" .. i], x, -20)
    end
    spin = spin - speed * dt * 0.12
    Transform.set_rotation(e.WheelBack, spin)
    Transform.set_rotation(e.WheelFront, spin)
    local bob = math.sin(t * (6 + speed * 0.08)) * (0.5 + k * 1.5)
    Transform.set_position(e.Car, -200, -175 + bob)
    Sprite.set_color(e.Underglow, 0.073, 0.787, 1.000, 0.45 + 0.35 * k)

    Text.set(e.Speed, tostring(math.floor(speed + 0.5)))
    local status
    if radio then
        status = "radio: " .. (STATIONS[Audio.get_music_clip()] or "tuning...") .. "   (N next station, R back to the score)"
    else
        status = "the score follows the speed   (R for the radio)"
    end
    UI.set_text(e.Status, status)
end
